import { useRef, useState } from "react";
import styled from "@emotion/styled";
import { GuideCue, GuideCueProps } from "@leafygreen-ui/guide-cue";
import { palette } from "@leafygreen-ui/palette";
import { differenceInDays } from "date-fns";
import Cookies from "js-cookie";
import { size } from "../../constants/tokens";
import Icon from "../Icon";

type Props = {
  activeDays?: number;
  cookieName: string;
  loading?: boolean;
};

/**
 * ExpiringAnnouncementTooltip displays a clickable info icon with a popover.
 * On first view, the popover opens automatically. Once dismissed, a cookie is set
 * and the popover stays closed on future visits. The info icon remains visible
 * for `activeDays` (default 8) after first dismissal, then disappears entirely.
 * @param props - React props
 * @param props.activeDays - number of days the info icon will persist after the tooltip is first viewed
 * @param props.cookieName - cookie associated with the view state
 * @param props.loading - whether data present in the tooltip is loading, helps avoid flickering tooltip
 * @returns React component
 */
export const ExpiringAnnouncementTooltip: React.FC<
  Props & Pick<GuideCueProps, "children" | "title" | "tooltipAlign">
> = ({ activeDays = 8, cookieName, loading = false, ...guideCueProps }) => {
  const now = new Date();
  const infoRef = useRef(null);

  const seenTooltipCookie: string | undefined = Cookies.get(cookieName);
  const neverSeenTooltip = !seenTooltipCookie;
  const seenTooltipDate = seenTooltipCookie ? new Date(seenTooltipCookie) : now;

  const [open, setOpen] = useState(neverSeenTooltip);

  const close = () => {
    setOpen(false);

    if (neverSeenTooltip) {
      Cookies.set(cookieName, seenTooltipDate.toString(), { expires: 365 });
    }
  };

  return !loading &&
    (neverSeenTooltip ||
      differenceInDays(now, seenTooltipDate) < activeDays) ? (
    <>
      <IconContainer ref={infoRef}>
        <Icon
          data-cy="announcement-tooltip-trigger"
          fill={palette.gray.dark2}
          glyph="InfoWithCircle"
          onClick={() => setOpen((o) => !o)}
        />
      </IconContainer>
      <GuideCue
        currentStep={1}
        numberOfSteps={1}
        onDismiss={close}
        onPrimaryButtonClick={close}
        open={open}
        refEl={infoRef}
        setOpen={setOpen}
        {...guideCueProps}
      />
    </>
  ) : null;
};

const IconContainer = styled.div`
  cursor: pointer;
  padding-left: ${size.xxs};
`;
import Cookie from "js-cookie";
import { MockInstance } from "vitest";
import {
  renderWithRouterMatch as render,
  screen,
  stubGetClientRects,
  userEvent,
  waitFor,
} from "../../test_utils";
import { ExpiringAnnouncementTooltip } from ".";

vi.mock("js-cookie");
const mockedGet = vi.spyOn(Cookie, "get") as MockInstance;
const mockedSet = vi.spyOn(Cookie, "set") as MockInstance;

describe("ExpiringAnnouncementTooltip", () => {
  beforeAll(() => {
    stubGetClientRects();
  });

  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.clearAllMocks();
    vi.useRealTimers();
  });

  const fakeDate = new Date(2025, 1, 1);
  const oneDayLater = new Date(2025, 1, 2);
  const twoWeeksLater = new Date(2025, 1, 15);

  describe("upon first view of tooltip", () => {
    it("renders with guide cue open if user has never seen it", async () => {
      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      await waitFor(() => {
        expect(screen.getByText("New Release")).toBeVisible();
      });
    });

    it("does not render if loading", async () => {
      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          loading
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      expect(screen.queryByText("New Release")).not.toBeInTheDocument();
    });

    it("closes the icon when the icon is clicked", async () => {
      const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );

      await waitFor(() => {
        expect(screen.getByText("New Release")).toBeVisible();
      });
      await user.click(screen.getByDataCy("announcement-tooltip-trigger"));
      await waitFor(() => {
        expect(screen.queryByText("New Release")).not.toBeVisible();
      });
    });

    it("sets a cookie with the date and expiration upon close", async () => {
      const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
      vi.setSystemTime(fakeDate);

      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      await waitFor(() => {
        expect(screen.getByText("New Release")).toBeVisible();
      });
      await user.click(screen.getByRole("button", { name: "Got it" }));

      await waitFor(() => {
        expect(screen.queryByText("New Release")).not.toBeVisible();
      });

      expect(mockedSet).toHaveBeenCalledExactlyOnceWith(
        "TEST_COOKIE",
        fakeDate.toString(),
        { expires: 365 },
      );
    });
  });

  describe("when user has already seen tooltip within one week", () => {
    it("doesn't open tooltip upon render", async () => {
      mockedGet.mockReturnValue(fakeDate.toString());
      vi.setSystemTime(oneDayLater);

      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      expect(mockedGet).toHaveBeenCalledOnce();
      expect(screen.queryByText("New Release")).not.toBeInTheDocument();
    });

    it("opens the tooltip when the button is clicked and doesn't update the cookie date on close", async () => {
      const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
      mockedGet.mockReturnValue(fakeDate.toString());
      vi.setSystemTime(oneDayLater);

      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      expect(mockedGet).toHaveBeenCalledOnce();
      expect(screen.queryByText("New Release")).not.toBeInTheDocument();

      await user.click(screen.getByDataCy("announcement-tooltip-trigger"));
      await waitFor(() => {
        expect(screen.getByText("New Release")).toBeVisible();
      });
      await user.click(screen.getByRole("button", { name: "Got it" }));
      await waitFor(() => {
        expect(screen.queryByText("New Release")).not.toBeInTheDocument();
      });
      expect(mockedSet).not.toHaveBeenCalled();
    });
  });

  describe("when user has seen tooltip two weeks ago", () => {
    it("does not show the popover icon", () => {
      mockedGet.mockReturnValue(fakeDate.toString());
      vi.setSystemTime(twoWeeksLater);

      render(
        <ExpiringAnnouncementTooltip
          cookieName="TEST_COOKIE"
          title="New Release"
        >
          Try out this feature
        </ExpiringAnnouncementTooltip>,
      );
      expect(
        screen.queryByLabelText("Info With Circle Icon"),
      ).not.toBeInTheDocument();
    });
  });
});

import { useEffect } from "react";
import styled from "@emotion/styled";
import { Checkbox } from "@leafygreen-ui/checkbox";
import { palette } from "@leafygreen-ui/palette";
import { size } from "../../constants/tokens";
import { FilterInputControls } from "./FilterInputControls";

const { gray } = palette;

export const ALL_VALUE = "all";
const ALL_COPY = "All";
export interface TreeSelectProps {
  isVisible?: boolean;
  onChange: (s: string[]) => void;
  setOptionsLabel?: (v: string) => void;
  state: string[];
  tData: TreeDataEntry[];
  onReset?: () => void;
  onFilter?: () => void;
  "data-cy"?: string;
}
export interface TreeDataChildEntry {
  title: string;
  value: string;
  key: string;
}
export interface TreeDataEntry extends TreeDataChildEntry {
  children?: TreeDataChildEntry[];
}

export const TreeSelect: React.FC<TreeSelectProps> = ({
  "data-cy": dataCy,
  isVisible = true,
  onChange,
  onFilter,
  onReset,
  setOptionsLabel = () => undefined,
  state,
  tData,
}) => {
  const allValues = getAllValues(tData);
  // removes values not included in tData
  const filteredState = state.filter((value) => allValues.includes(value));
  const optionsLabel = filteredState.includes(ALL_VALUE)
    ? ALL_COPY
    : filteredState
        .reduce(
          // remove children nodes if parent exists in state
          (accum, value) => {
            const { target } = findNode({ value, tData });
            if (target.children) {
              return accum.filter(
                // @ts-expect-error: FIXME. This comment was added by an automated script.
                (v) => !target.children.find((child) => child.value === v),
              );
            }
            return accum;
          },
          [...filteredState],
        )
        .map((value) => findNode({ value, tData }).target.title)
        .join(", ");

  useEffect(() => {
    setOptionsLabel(optionsLabel);
  }, [optionsLabel, setOptionsLabel]);

  if (!isVisible) {
    return null;
  }

  return (
    <CheckboxContainer data-cy={dataCy || "tree-select-options"}>
      {renderCheckboxes({
        state: filteredState,
        tData,
        onChange,
      })}
      {onReset && onFilter && (
        <FilterInputControls
          onClickReset={onReset}
          onClickSubmit={onFilter}
          submitButtonCopy="Filter"
        />
      )}
    </CheckboxContainer>
  );
};

// depth first traversal checkbox data.
// pushes parent then children to rows array
// keeps track of level for indentation
const renderCheckboxes = ({
  onChange,
  state,
  tData,
}: {
  tData: TreeDataEntry[];
  state: string[];
  onChange: (v: [string]) => void;
}): React.JSX.Element[] => {
  const rows: React.JSX.Element[] = [];
  tData.forEach((entry) => {
    // @ts-expect-error: FIXME. This comment was added by an automated script.
    renderCheckboxesHelper({ rows, data: entry, onChange, state, tData });
  });
  return rows;
};

const renderCheckboxesHelper = ({
  data,
  onChange,
  rows,
  state,
  tData,
}: {
  rows: React.JSX.Element[];
  data: TreeDataEntry;
  onChange: (v: string[]) => void;
  state: string[];
  tData: TreeDataEntry[];
}): void => {
  // push parent
  const onChangeFn = (): void =>
    handleOnChange({ state, value: data.value, onChange, tData });
  rows.push(
    <CheckboxWrapper key={data.key} isAll={data.value === ALL_VALUE} level={0}>
      <Checkbox
        bold={false}
        checked={state.includes(data.value)}
        className="cy-checkbox"
        data-cy="checkbox"
        label={data.title}
        onChange={onChangeFn}
      />
    </CheckboxWrapper>,
  );
  // then examine children
  if (data.children) {
    data.children.forEach((child) => {
      const onChangeChildFn = (): void =>
        handleOnChange({ state, value: child.value, onChange, tData });
      rows.push(
        <CheckboxWrapper
          key={`${data.key}-${child.key}`}
          isAll={child.value === ALL_VALUE}
          level={1}
        >
          <Checkbox
            bold={false}
            checked={state.includes(child.value)}
            className="cy-checkbox"
            data-cy="checkbox"
            label={child.title}
            onChange={onChangeChildFn}
          />
        </CheckboxWrapper>,
      );
    });
  }
};

// Executes when checkbox is clicked
const handleOnChange = ({
  onChange,
  state,
  tData, // callback function
  value,
}: {
  state: string[];
  value: string;
  onChange: (v: string[]) => void;
  tData: TreeDataEntry[];
}): void => {
  const isAlreadyChecked = state.includes(value); // is checkbox already selected
  const { parent, siblings, target } = findNode({ value, tData });
  const isParent = target.children;
  const isAll = target.value === ALL_VALUE; // is all button clicked
  if (!target) {
    onChange([...state]);
  }
  // is all button checked
  if (isAll) {
    if (isAlreadyChecked) {
      onChange([]);
    } else {
      onChange(getAllValues(tData));
    }
  } else if (isParent) {
    // has list of children
    // @ts-expect-error: FIXME. This comment was added by an automated script.
    const childrenValues = target.children.map((child) => child.value);
    if (isAlreadyChecked) {
      onChange(
        adjustAll({
          resultState: state.filter(
            (v) => v !== value && !childrenValues.includes(v),
          ),
          tData,
        }),
      );
    } else {
      const resultState = Array.from(
        new Set([...state, value, ...childrenValues]),
      );
      onChange(adjustAll({ resultState, tData }));
    }
  } else {
    // does not have list of children, could be child
    const parentValue = parent ? parent.value : "";
    if (isAlreadyChecked) {
      onChange(
        adjustAll({
          resultState: state.filter((v) => v !== value && v !== parentValue),
          tData,
        }),
      );
    } else {
      let siblingsChecked = true;
      siblings.forEach((sibling) => {
        siblingsChecked = siblingsChecked && state.includes(sibling.value);
      });
      const shouldCheckParent = parentValue && siblingsChecked;
      // use set in case parent.value already exists in state
      const resultState = Array.from(
        new Set(
          [...state, value].concat(shouldCheckParent ? [parentValue] : []),
        ),
      );
      onChange(adjustAll({ resultState, tData }));
    }
  }
};

// selects or deselects the All checkbox depending on current options
const adjustAll = ({
  resultState,
  tData,
}: {
  resultState: string[];
  tData: TreeDataEntry[];
}): string[] => {
  const allValues = getAllValues(tData).filter((value) => value !== ALL_VALUE);
  const resultStateHasAllValues = allValues.reduce(
    (accum, value) => accum && resultState.includes(value),
    true,
  );
  // convert to set in case all exists in URL when its not supposed to
  const resultStateSet = new Set(resultState);
  if (resultStateHasAllValues) {
    resultStateSet.add(ALL_VALUE);
  } else {
    resultStateSet.delete(ALL_VALUE);
  }
  return Array.from(resultStateSet);
};

interface FindNodeResult {
  target: TreeDataEntry;
  parent: TreeDataEntry;
  siblings: TreeDataEntry[] | TreeDataChildEntry[];
}

const findNode = ({
  tData,
  value,
}: {
  value: string;
  tData: TreeDataEntry[];
}): FindNodeResult => {
  for (const curr of tData) {
    if (curr.value === value) {
      return {
        target: curr,
        // @ts-expect-error: FIXME. This comment was added by an automated script.
        parent: null,
        siblings: tData.filter((v) => v.value !== value),
      };
    }
    if (curr.children) {
      const child = curr.children.find((c) => c.value === value);
      if (child) {
        return {
          target: child,
          parent: curr,
          siblings: curr.children.filter((c) => c.value !== value),
        };
      }
    }
  }
  return {
    // @ts-expect-error: FIXME. This comment was added by an automated script.
    target: null,
    // @ts-expect-error: FIXME. This comment was added by an automated script.
    parent: null,
    siblings: [],
  };
};

// returns all values in tData from parents and children
const getAllValues = (tData: TreeDataEntry[]): string[] =>
  tData.reduce((accum, currNode) => {
    const childrenValues = currNode.children
      ? currNode.children.map((child) => child.value)
      : [];
    // @ts-expect-error: FIXME. This comment was added by an automated script.
    return accum.concat([currNode.value]).concat(childrenValues);
  }, []);

