const getErrorMessage = (response: Response, method: string) => {
  const { status, statusText } = response;
  return `${method} Error: ${status} - ${statusText}`;
};

export const fetchWithRetry = <T = unknown>(
  url: string,
  options: RequestInit,
  retries: number = 3,
  backoff: number = 150,
): Promise<{ data: T }> =>
  new Promise((resolve, reject) => {
    const attemptFetch = (attempt: number): void => {
      fetch(url, options)
        .then((res) => {
          if (res.ok) {
            return res.json();
          }
          reject(
            new Error(getErrorMessage(res, "GET"), {
              cause: { message: res.statusText, statusCode: res.status },
            }),
          );
        })
        .then((data) => resolve(data))
        .catch((err) => {
          if (attempt <= retries) {
            setTimeout(() => attemptFetch(attempt + 1), backoff * attempt);
          } else {
            reject(err);
          }
        });
    };
    attemptFetch(1);
  });
import { reportError } from "../errorReporting";

const headers = new Headers({
  "Content-Type": "application/json",
});

export const post = async (
  url: string,
  body: unknown,
  handleError?: (e: Error) => void,
) => {
  try {
    const options: RequestInit = {
      body: JSON.stringify(body),
      credentials: "include",
      headers,
      method: "POST",
    };
    const response = await fetch(url, options);
    if (!response.ok) {
      throw new Error(getErrorMessage(response, "POST"));
    }
    return response;
  } catch (e) {
    const err = e instanceof Error ? e : new Error(JSON.stringify(e));
    reportError(err).warning();
    handleError?.(err);
  }
};

const getErrorMessage = (response: Response, method: string) => {
  const { status, statusText } = response;
  return `${method} Error: ${status} - ${statusText}`;
};

