import { MockedProvider } from "@apollo/client/testing/react";
import LeafyGreenProvider from "@leafygreen-ui/leafygreen-provider";
import { Decorator, Parameters, Preview } from "@storybook/react-vite";
import { createMemoryRouter, RouterProvider } from "react-router-dom";

const parameters: Parameters = {
  actions: { argTypesRegex: "^on[A-Z].*" },
  apolloClient: {
    MockedProvider: ({ children }: { children: React.ReactNode }) => children,
  },
  controls: {
    matchers: {
      color: /(background|color)$/i,
      date: /Date$/,
    },
  },
};

const decorators: Decorator[] = [
  (Story) => (
    <LeafyGreenProvider>
      <Story />
    </LeafyGreenProvider>
  ),
  (
    Story,
    {
      parameters: {
        apolloClient: { MockedProvider: _, ...rest },
      },
    },
  ) => (
    <MockedProvider {...rest}>
      <Story />
    </MockedProvider>
  ),
  (Story, context) => {
    const { parameters: storyParameters } = context;
    const { reactRouter } = storyParameters;
    const { params, path, route } = reactRouter || {};
    const routes = [
      {
        path: path || "/",
        parameters: params || {},
        element: <Story />,
        errorElement: <div>Failed to render component.</div>,
      },
    ];
    const memoryRouter = createMemoryRouter(routes, {
      initialEntries: [route || "/"],
    });
    return <RouterProvider router={memoryRouter} />;
  },
];

const preview: Preview = {
  parameters,
  decorators,
};

export default preview;

import React from "react";
import { createRoot } from "react-dom/client";
import { initializeErrorHandling } from "@evg-ui/lib/utils/errorReporting";
import {
  initializeHoneycomb,
  injectOpenTelemetryAttributeStoreIntoWindow,
} from "@evg-ui/lib/utils/observability";
import { toEscapedRegex } from "@evg-ui/lib/utils/string";
import {
  evergreenURL,
  getReleaseStage,
  isDevelopmentBuild,
} from "utils/environmentVariables";
import App from "./App";
import routes, { slugs } from "./constants/routes";

const routeConfig = {
  ...routes,
  // Override the testLogs route to include the groupID parameter so that we can easily identify routes with groupID slugs in Honeycomb.
  testLogs: `${routes.testLogs}/:${slugs.groupID}?`,
};
initializeErrorHandling({
  environment: getReleaseStage(),
  isProductionBuild: !isDevelopmentBuild(),
  sentryDSN: process.env.REACT_APP_PARSLEY_SENTRY_DSN || "",
});
initializeHoneycomb({
  appVersion: process.env.REACT_APP_VERSION || "",
  backendURL: toEscapedRegex(evergreenURL || ""),
  debug: isDevelopmentBuild(),
  endpoint: process.env.REACT_APP_HONEYCOMB_ENDPOINT || "",
  environment: getReleaseStage(),
  ingestKey: process.env.REACT_APP_HONEYCOMB_INGEST_KEY || "",
  routeConfig,
  serviceName: "parsley",
});
injectOpenTelemetryAttributeStoreIntoWindow();

// Reload on stale chunk errors after deploys so users get the latest assets.
window.addEventListener("vite:preloadError", () => {
  window.location.reload();
});

createRoot(document.getElementById("root") as HTMLElement).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);
