    accessorFn: ({ uptime }) => new Date(uptime),
    enableSorting: true,
    cell: ({ getValue }) => formatDistanceToNow(getValue() as Date),
  },
  {
    header: "Actions",
    cell: ({ row }) => <SpawnHostTableActions host={row.original} />,
  },
];

