import '../src/index.css'; // import global styles
import { SessionProvider } from '../src/contexts/SessionContext';

const preview: Preview = {
  decorators: [
    (Story) => (
      <SessionProvider>
        <Story />
      </SessionProvider>
    ),
  ],
  async beforeEach() {
    localStorage.setItem('theme', 'dark');
    localStorage.setItem('sidebar:open', 'true');
