import { TaskStatus, TaskStatusUmbrella } from "../types/task";

export const taskStatusToCopy: Record<TaskStatus | TaskStatusUmbrella, string> =
  {
    [TaskStatus.Aborted]: "Aborted",
    [TaskStatus.Blocked]: "Blocked",
    [TaskStatus.Dispatched]: "Dispatched",
    [TaskStatus.Failed]: "Failed",
    [TaskStatus.KnownIssue]: "Known Issue",
    [TaskStatus.Pending]: "Pending",
    [TaskStatus.Started]: "Running",
    [TaskStatus.SystemFailed]: "System Failed",
    [TaskStatus.SystemTimedOut]: "System Timed Out",
    [TaskStatus.SystemUnresponsive]: "System Unresponsive",
    [TaskStatus.SetupFailed]: "Setup Failed",
    [TaskStatus.Succeeded]: "Succeeded",
    [TaskStatus.TaskTimedOut]: "Task Timed Out",
    [TaskStatus.TestTimedOut]: "Test Timed Out",
    [TaskStatus.Unstarted]: "Unstarted",
    [TaskStatus.Unscheduled]: "Unscheduled",
    [TaskStatus.WillRun]: "Will Run",
    [TaskStatus.Inactive]: "Inactive",
    [TaskStatus.Undispatched]: "Undispatched",

    [TaskStatusUmbrella.Scheduled]: "Scheduled",
    [TaskStatusUmbrella.Failed]: "Failed",
    [TaskStatusUmbrella.Running]: "Running",
    [TaskStatusUmbrella.SystemFailure]: "System Failed",
    [TaskStatusUmbrella.Undispatched]: "Undispatched",
  };
export enum TaskStatus {
  Inactive = "inactive",

  // TaskUnstarted is assigned to a display task after cleaning up one of
  // its execution tasks. This indicates that the display task is
  // pending a rerun
  Unstarted = "unstarted",

  // TaskUndispatched indicates either
  //  1. a task is not scheduled to run (when Task.Activated == false)
  //  2. a task is scheduled to run (when Task.Activated == true)
  Undispatched = "undispatched",
  WillRun = "will-run",
  Unscheduled = "unscheduled",

  // TaskStarted indicates a task is currently running
  Started = "started",

  // TaskDispatched indicates that an agent has received the task, but
  // the agent has not yet told Evergreen that it's running the task
  Dispatched = "dispatched",

  // This is a temporary status which is the same as undispatched, but
  // with the additional info that it's waiting for a dependency
  Pending = "pending",

  // The statuses below indicate that a task has finished.
  Succeeded = "success",

  // These statuses indicate that the task failed, and it is likely a problem
  // with the code being tested
  Failed = "failed",
  TestTimedOut = "test-timed-out",
  TaskTimedOut = "task-timed-out",

  // These statuses indicate that the task failed, and it is likely a problem
  // with the systems running the task
  SetupFailed = "setup-failed",
  SystemFailed = "system-failed",
